package com.autoops.machine.service;import com.autoops.machine.repository.MachineRepository;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import java.security.MessageDigest;import java.util.HexFormat;@Service public class SshHostTrustService{private final MachineRepository machines;public SshHostTrustService(MachineRepository m){machines=m;}public String fingerprint(String hostKey){try{return "SHA256:"+HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256").digest(hostKey.getBytes()));}catch(Exception e){throw new IllegalStateException(e);}}@Transactional public void trust(Long machineId,String hostKey,String expectedFingerprint){var m=machines.findById(machineId).orElseThrow();String actual=fingerprint(hostKey);if(!actual.equals(expectedFingerprint))throw new IllegalArgumentException("SSH fingerprint mismatch");m.setSshHostKey(hostKey);m.setSshFingerprint(actual);m.markFingerprintVerified();machines.save(m);}@Transactional(readOnly=true)public void verify(Long machineId,String presentedHostKey){var m=machines.findById(machineId).orElseThrow();if(m.getSshFingerprint()==null)throw new IllegalStateException("SSH host is not trusted");if(!m.getSshFingerprint().equals(fingerprint(presentedHostKey)))throw new SecurityException("SSH host key changed");}}
